(36417, 'frFR', 'Avatar de Sephraliss', 'La bataille s\’achève lors de la restauration complète de l\’avatar de Sephraliss.', 69497),
(36416, 'frFR', 'Section 18', '', 69497),
(18515, 'frFR', 'Section 14', '$[!8,23\n\nEn mode mythique, plusieurs orbes de |cFF2959D3|Hspell:1300871|h[Force vitale corrompue]|h|r se forment.\n$]', 69497),
