(3119, 'frFR', 'Académie d\’Algeth\’ar', '', 69497),
(3116, 'frFR', 'Siège du triumvirat', '', 69497),
(3319, 'frFR', 'Le tombeau d\’Ula\’tek', 'Frayez-vous un chemin jusqu\’au cœur de l\’abîme Venimeux pour affronter Ula\’tek.', 69497),
(3318, 'frFR', 'Le dédale des Serpents', 'Les antiques salles qui servaient de tombeau aux victimes des Entortillâmes sont à présent la demeure de monstrueuses créatures serpentines.', 69497),
(3317, 'frFR', 'L\’essence du venin', 'Dans la chambre de la Virulence, Vashnik le Malveillant distille les venins d\’Ula\’tek pour les rendre encore plus mortels.', 69497),
(3316, 'frFR', 'Les Entortillâmes', 'Nek\’zali l\’Entortillâme menace une fois de plus de déchaîner des horreurs innommables sur Azeroth.', 69497),
(3320, 'frFR', 'Le tombeau d\’Ula\’tek', 'Frayez-vous un chemin jusqu\’au cœur de l\’abîme Venimeux pour affronter Ula\’tek.', 69497);
